import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import PageStructure from 'flarum/forum/components/PageStructure';
import IndexSidebar from 'flarum/forum/components/IndexSidebar';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import Icon from 'flarum/common/components/Icon';
import humanTime from 'flarum/common/helpers/humanTime';
import extractText from 'flarum/common/utils/extractText';
import { showGame, wipeGame } from '../../common/api';
import { formatScore } from '../../common/format';
import Cabinet from '../components/Cabinet';
import Board from '../components/Board';
import { personLink } from '../components/Person';
import { t } from '../t';

/** /arcade/:slug — the game in its cabinet, with the leaderboard rail beside it. */
export default class GamePage extends Page {
  game = null;
  missing = false;
  version = 0;
  onPush = e => {
    const gameId = e.detail?.gameId;
    if (this.game && gameId === this.game.id) this.refresh();
  };
  oninit(vnode) {
    super.oninit(vnode);
    app.history.push('insert-coin.game', extractText(t('home.title')));
    showGame(m.route.param('slug')).then(game => {
      this.game = game;
      app.setTitle(game.title);
      m.redraw();
    }, () => {
      this.missing = true;
      m.redraw();
    });
  }
  oncreate(vnode) {
    super.oncreate(vnode);
    window.addEventListener('insertcoin:score', this.onPush);
  }
  onremove(vnode) {
    super.onremove(vnode);
    window.removeEventListener('insertcoin:score', this.onPush);
  }

  /** The champion line and the board, after a run or a realtime push. */
  refresh() {
    this.version++;
    if (!this.game) return;
    showGame(this.game.slug).then(game => {
      if (this.game) this.game.champion = game.champion;
      m.redraw();
    });
  }
  view() {
    const game = this.game;
    return m(PageStructure, {
      className: "InsertCoinPage InsertCoinGamePage",
      sidebar: () => m(IndexSidebar, null)
    }, game ? this.content(game) : this.missing ? m("p", {
      className: "InsertCoinEmpty"
    }, t('game.missing')) : m(LoadingIndicator, {
      display: "block"
    }));
  }
  content(game) {
    const champion = game.champion;
    return m("div", {
      className: "InsertCoinGame"
    }, m("nav", {
      className: "InsertCoinGame-crumbs"
    }, m(Link, {
      href: app.route('insert-coin.home')
    }, m(Icon, {
      name: "fas fa-arrow-left"
    }), " ", t('home.title')), game.category ? m("span", null, game.category.name) : null), m("div", {
      className: "InsertCoinGame-head"
    }, m("h2", {
      className: "InsertCoinGame-title"
    }, game.title), m("div", {
      className: "InsertCoinGame-badges"
    }, m("span", {
      className: "InsertCoinBadge"
    }, m(Icon, {
      name: game.mobile ? 'fas fa-mobile-screen' : 'fas fa-keyboard'
    }), " ", t(game.mobile ? 'card.mobile' : 'card.keyboard')), m("span", {
      className: "InsertCoinBadge"
    }, m(Icon, {
      name: "fas fa-play"
    }), " ", t('game.plays', {
      count: game.plays
    })), game.crownApproval ? m("span", {
      className: "InsertCoinBadge"
    }, m(Icon, {
      name: "fas fa-shield-halved"
    }), " ", t('game.crown_approval')) : null)), m("div", {
      className: "InsertCoinGame-body"
    }, m("div", {
      className: "InsertCoinGame-main"
    }, m(Cabinet, {
      game: game,
      onfinish: () => this.refresh()
    }), m("div", {
      className: "InsertCoinGame-champion"
    }, champion?.user ? m('[', null, personLink(champion.user, true), m("span", {
      className: "InsertCoinGame-championText"
    }, t('game.champion', {
      score: m("b", null, formatScore(champion.score, game.scoreLabel))
    }), champion.since ? m("span", {
      className: "InsertCoinGame-since"
    }, " \xB7 ", humanTime(new Date(champion.since))) : null)) : m("span", {
      className: "InsertCoinGame-championText"
    }, m(Icon, {
      name: "fas fa-crown"
    }), " ", t('game.no_champion'))), game.description ? m("p", {
      className: "InsertCoinGame-description"
    }, game.description) : null, app.forum.attribute('canModerateArcade') ? m(Button, {
      className: "Button Button--link InsertCoinGame-wipe",
      icon: "fas fa-eraser",
      onclick: () => confirm(extractText(t('moderate.wipe_game_confirm', {
        game: game.title
      }))) && wipeGame(game.id).then(() => this.refresh())
    }, t('moderate.wipe_game')) : null), m("aside", {
      className: "InsertCoinGame-rail"
    }, m(Board, {
      game: game,
      version: this.version
    }))));
  }
}
flarum.reg.add('ernestdefoe-insert-coin', 'forum/pages/GamePage', GamePage);